def find_largest_palindromic_cube(N: int) -> int:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    largest_palindromic_cube = 0
    cube_root_N = int(N ** (1/3))

    for number in range(1, cube_root_N + 1):
        cube = number ** 3
        if cube <= N and is_palindrome(str(cube)):
            largest_palindromic_cube = cube

    return largest_palindromic_cube
